const RepWorkspace=(()=>{
 const e=RepLocal.escape;
 let sessionChannel;const chatControllers=new Map();
 let host,ready=false,failure='',profile=null,setup={},voice=null,narration=null,video=null,documents=[],links=[],events=[],labels=[],videos=[],analyses=[],trajectoryDemos=[],libraryVideoId='',videoFilter='all',welcomeDraft='',welcomeFromDetail=false,inviteVideoId='',analysisVideoId='',analysisDoctorId='',analysisDrafts={},swipeStart=null,swipeSuppressClickUntil=0,query='',results=null,recording='',busy=false,photoBusy=false,recordEpoch=0,aborter,urls=[],activeRoute='',activeParams={},activeDoctor='',studioStep=1,checking=false,loadingToken=0,expertKey='drug',expertChats={drug:[],insurance:[],compliance:[]},expertDrafts={drug:'',insurance:'',compliance:''},expertPending=new Set(),expertStreaming=new Map(),expertThinking=new Map(),chatEpoch=0;
 const WELCOME_TEXT='尊敬的医生，您好。我是赛生生物上海区域医学信息代表卢劲百。我负责日达仙产品学术信息沟通和临床服务协调。您需要学术资料、会议信息或产品信息支持，我会在合规前提下及时、准确提供。您可通过或企业微信联系我，我会在工作时间及时回复。感谢您的时间，祝工作顺利。';
 const VOICE_TEXT='您好，我是您的医药代表。很高兴通过知药与您交流。我会认真聆听您的学术需求，为您整理日达仙相关资料，协助您查找原文、核对来源，并及时跟进您关注的问题。期待与您保持沟通。';
 const options={kol:['待评估','全国级 KOL','区域级 KOL','院内骨干','临床医生'],stage:['待评估','初步了解','资料研读','临床关注','持续交流'],payment:['待了解','关注商保覆盖','关注理赔流程','关注患者自付','暂无明确偏好']};
 let scriptKey=RepVideoTemplates[0].id;
 const videoTemplate=record=>RepVideoTemplates.find(item=>item.id===record?.templateId);
 const videoSource=record=>record?.blob?objectURL(record.blob):record?.templateId===RepKnowledgeVideo.id?RepKnowledgeVideo.src:videoTemplate(record)?.src||(record?.templateId==='welcome'?'https://101.132.38.176/media/20261116/intro-v3.mp4':'');
 const videoFallback=record=>record?.blob?'':record?.templateId===RepKnowledgeVideo.id?RepKnowledgeVideo.fallbackSrc:videoTemplate(record)?.fallbackSrc||(record?.templateId==='welcome'?'assets/welcome-intro-20261116.mp4':'');
 document.addEventListener('error',event=>{const media=event.target,fallback=media?.dataset?.fallbackSrc;if(media?.tagName==='VIDEO'&&fallback&&media.src!==new URL(fallback,location.href).href){media.src=fallback;media.load();}},true);
 const videoPoster=record=>record?.templateId==='welcome'?'assets/welcome-intro-20261116.jpg':record?.templateId===RepKnowledgeVideo.id?RepKnowledgeVideo.poster:videoTemplate(record)?.poster||record?.photo||profile?.photo||'';
 const fmt=at=>new Date(at).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'});
 const select=(name,values,value)=>`<select name="${name}" class="rw-input">${values.map(v=>`<option ${v===value?'selected':''}>${e(v)}</option>`).join('')}</select>`;
 const button=(action,text,secondary=false)=>`<button type="button" class="${secondary?'secondary-button':'primary-button'}" data-rw="${action}" ${busy||checking?'disabled':''}>${text}</button>`;
 const objectURL=blob=>{const u=URL.createObjectURL(blob);urls.push(u);return u;};
 const blank=text=>`<div class="rw-empty">${text}</div>`;
 const publishDate=at=>new Date(at).toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'});
 const fullDate=at=>new Date(at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});
 const orderedVideos=()=>videos.slice().sort((a,b)=>Date.parse(b.at)-Date.parse(a.at)||String(b.id).localeCompare(String(a.id)));
 const videoTitle=record=>record?.templateId==='welcome'?'欢迎视频':record?.templateId===RepKnowledgeVideo.id?RepKnowledgeVideo.title:videoTemplate(record)?.title||record?.script||`${record?.name||'我的'}的介绍`;
 const videoTag=record=>record?.templateId==='welcome'?'欢迎介绍':({oncology:'肿瘤治疗',perioperative:'肺癌围术期',pd1:'免疫治疗','knowledge-answer':'知识问答'}[record?.templateId]||'其他视频');
 function selectedVideo(){return videos.find(record=>record.id===libraryVideoId)||orderedVideos()[0];}
 function invitationVideo(){return videos.find(record=>record.id===inviteVideoId)||videos.find(record=>record.id===video?.videoId)||video;}
 const randomCount=(min,max)=>min+Math.floor(Math.random()*(max-min+1));
 function makeEngagementDemo(){const pool=host.doctors.map(doctor=>doctor.id);for(let i=pool.length-1;i>0;i--){const j=randomCount(0,i);[pool[i],pool[j]]=[pool[j],pool[i]];}const invited=randomCount(8,pool.length),viewed=randomCount(4,invited-1),played=randomCount(2,viewed-1),completed=randomCount(1,played-1);return {version:1,doctors:pool.slice(0,invited).map((doctorId,index)=>({doctorId,stage:index<completed?'complete':index<played?'play':index<viewed?'open':'invited',plays:index<played?randomCount(1,4):0}))};}
 async function ensureEngagementDemos(){const changed=[];for(const record of videos){if(record.engagementDemo?.version!==1){record.engagementDemo=makeEngagementDemo();changed.push(record);}}const current=videos.find(record=>record.id===video?.videoId);if(current&&video.engagementDemo?.version!==1){video={...video,engagementDemo:current.engagementDemo};changed.push(video);}if(changed.length)await RepLocal.putMany(changed);}
 async function migrateVideoHistory(){
  if(video){let archived=videos.find(record=>record.id===video.videoId)||videos.find(record=>record.at===video.at&&record.name===video.name&&record.templateId===video.templateId&&record.script===video.script);if(!archived){archived={...video,id:RepLocal.uid('video:'),repId:video.repId||profile?.repId};archived.videoId=archived.id;videos.push(archived);video={...video,videoId:archived.id};await RepLocal.putMany([archived,video]);}else if(video.videoId!==archived.id){video={...video,videoId:archived.id};await RepLocal.put(video);}}
  videos=videos.filter(record=>!record.repId||record.repId===profile?.repId);await ensureEngagementDemos();
 }
 function linkedVideo(link){if(link.videoId)return videos.find(record=>record.id===link.videoId);return orderedVideos().find(record=>record.templateId===link.templateId&&record.script===link.script&&record.name===link.name&&Date.parse(record.at)<=Date.parse(link.at));}
 function videoReach(record){const invitations=links.filter(link=>linkedVideo(link)?.id===record.id),ids=new Set(invitations.map(link=>link.id)),activity=events.filter(event=>ids.has(event.linkId)),rank={invited:0,open:1,play:2,complete:3},rows=new Map((record.engagementDemo?.doctors||[]).map(row=>[row.doctorId,{...row}]));for(const link of invitations)if(!rows.has(link.doctorId))rows.set(link.doctorId,{doctorId:link.doctorId,stage:'invited',plays:0});for(const event of activity){if(!['open','play','complete'].includes(event.type))continue;const row=rows.get(event.doctorId)||{doctorId:event.doctorId,stage:'invited',plays:0};if(rank[event.type]>rank[row.stage])row.stage=event.type;if(event.type==='play')row.plays++;if(event.type==='complete')row.plays=Math.max(1,row.plays);rows.set(event.doctorId,row);}const doctors=[...rows.values()];return {invitations,activity,doctors,invited:doctors.length,viewed:doctors.filter(row=>row.stage!=='invited').length,plays:doctors.reduce((sum,row)=>sum+row.plays,0),completed:doctors.filter(row=>row.stage==='complete').length};}
 function videoStatsMarkup(record){const stats=videoReach(record);return `<div class="rw-video-metrics"><div><strong>${stats.invited}</strong><span>已邀请 · 位</span></div><div><strong>${stats.viewed}</strong><span>已查看 · 位</span></div><div><strong>${stats.plays}</strong><span>播放 · 次</span></div><div><strong>${stats.completed}</strong><span>看完 · 位</span></div></div>`;}

 function videoDoctorsMarkup(record){const stats=videoReach(record);return `<div class="rw-video-doctors">${stats.doctors.map(row=>{const doctor=host.doctors.find(item=>item.id===row.doctorId),status={complete:'已看完',play:'已播放',open:'已查看',invited:'未查看'}[row.stage];return `<div class="rw-video-doctor" data-video-doctor="${e(row.doctorId)}"><span class="doctor-avatar">${e(doctor?.name?.[0]||'医')}</span><div><strong>${e(doctor?.name||'医生')}</strong><span>${e(doctor?.hospital||'')}${row.plays?' · 播放 '+row.plays+' 次':''}</span></div><span class="rw-watch-status ${status==='未查看'?'pending':''}">${status}</span></div>`;}).join('')}</div>`;}
 function videoPreview(record){return `<video id="rw-library-video" class="rw-video rw-template-video" controls controlslist="nodownload" playsinline webkit-playsinline preload="auto" poster="${e(videoPoster(record))}" src="${e(videoSource(record))}" data-fallback-src="${e(videoFallback(record))}" aria-label="${e(videoTitle(record))}"></video>`;}
 function videoCardStats(record){const stats=videoReach(record);return `<div class="rw-video-card-stats" aria-label="医生查看数据"><span><strong>${stats.invited}</strong><small>邀请医生</small></span><span><strong>${stats.viewed}</strong><small>已查看</small></span><span><strong>${stats.plays}</strong><small>播放次数</small></span><span><strong>${stats.completed}</strong><small>已看完</small></span></div>`;}
 function digitalVideos(){
  const list=orderedVideos(),filtered=list.filter(item=>videoFilter==='all'||videoTag(item)===videoFilter);
  if(!list.length)return `<section class="panel rw-card"><h2>还没有已生成的视频</h2>${button('welcome','创建欢迎视频')}</section>`;
  const filters=['all','欢迎介绍','肿瘤治疗','肺癌围术期','免疫治疗','知识问答'].filter(tag=>tag==='all'||list.some(item=>videoTag(item)===tag));
  return `<section class="panel rw-card rw-create-video-card"><div><h3>创建新视频</h3><span class="tag rw-video-total">${list.length} 个视频</span></div>${button('scripts','选择话术')}</section>
   <section class="panel rw-card rw-video-list-card"><div class="rw-heading"><h3>已生成视频</h3><span class="rw-list-count">按生成时间排序</span></div><div class="rw-video-filters" role="group" aria-label="视频标签筛选">${filters.map(tag=>`<button type="button" data-rw-filter="${e(tag)}" class="${videoFilter===tag?'active':''}" aria-pressed="${videoFilter===tag}">${tag==='all'?'全部':e(tag)}</button>`).join('')}</div><div class="rw-video-list">${filtered.map(record=>`<article class="rw-video-list-item" data-video-id="${e(record.id)}"><div class="rw-video-swipe-actions"><button type="button" data-rw-regenerate="${e(record.id)}" tabindex="-1">重新生成</button><button type="button" class="danger" data-rw-delete="${e(record.id)}" tabindex="-1">删除</button></div><div class="rw-video-swipe-content"><button class="rw-video-row" type="button" data-rw-select="${e(record.id)}" aria-label="查看${e(videoTitle(record))}详情，左滑可管理视频"><img src="${e(videoPoster(record))}" alt=""><span class="rw-video-row-copy"><strong>${e(videoTitle(record))}</strong><span class="rw-video-row-meta"><time datetime="${e(record.at)}">${fullDate(record.at)}</time><b class="rw-video-kind">${e(videoTag(record))}</b><b class="rw-video-status">已生成</b></span><span class="rw-video-row-brief">${e(record.templateId==='welcome'?record.script:videoTitle(record))}</span></span><span class="rw-row-chevron" aria-hidden="true">›</span></button>${videoCardStats(record)}</div></article>`).join('')||'<p class="rw-list-empty">当前标签下暂无视频</p>'}</div></section>`;
 }
 function videoDetail(){
  const current=selectedVideo();if(!current)return `<section class="panel rw-card"><h2>视频不存在</h2>${button('avatar','返回我的数字人')}</section>`;
  return `<section class="panel rw-card rw-library-card rw-video-detail-media">${videoPreview(current)}<div class="rw-video-detail-heading"><span class="rw-video-kind">${e(videoTag(current))}</span><span class="rw-video-status">已生成</span></div><h2 class="rw-library-title">${e(videoTitle(current))}</h2><time class="rw-library-time" datetime="${e(current.at)}">创建时间：${fullDate(current.at)}</time>${current.templateId==='welcome'?`<p class="rw-welcome-caption">${e(current.script)}</p>`:''}</section>
   <section class="panel rw-card rw-video-detail-reach"><div class="rw-heading"><h3>医生查看情况</h3><button class="text-btn" data-rw="sync">刷新</button></div><div id="rw-library-stats">${videoStatsMarkup(current)}</div><div id="rw-library-doctors">${videoDoctorsMarkup(current)}</div></section><div class="rw-video-invite-dock">${button('video-invite','邀请医生')}</div>`;
 }
 function analysisKey(){return `analysis:${analysisVideoId}:${analysisDoctorId}`;}
 function analysisText(){const key=analysisKey();return Object.prototype.hasOwnProperty.call(analysisDrafts,key)?analysisDrafts[key]:analyses.find(record=>record.id===key)?.text||'';}
 function rememberAnalysisDraft(){const area=document.getElementById('rw-analysis-text');if(area&&analysisVideoId)analysisDrafts[analysisKey()]=area.value;}
 function openVideoAnalysis(){const current=selectedVideo();if(!current)return;analysisVideoId=current.id;analysisDoctorId=videoReach(current).invitations[0]?.doctorId||host.doctors[0]?.id||'';host.modal('给医生的分析',`<div class="rw-analysis-video"><strong>${e(videoTitle(current))}</strong><time>${fullDate(current.at)}</time></div>${videoStatsMarkup(current)}<label class="rw-label" for="rw-analysis-doctor">对应医生</label><select id="rw-analysis-doctor" class="rw-input">${host.doctors.map(doctor=>`<option value="${doctor.id}" ${doctor.id===analysisDoctorId?'selected':''}>${e(doctor.name)} · ${e(doctor.hospital)}</option>`).join('')}</select><label class="rw-label" for="rw-analysis-text">分析内容</label><textarea id="rw-analysis-text" class="rw-input" rows="6" maxlength="2000" placeholder="填写视频重点、医生关注的问题及沟通建议">${e(analysisText())}</textarea><div class="rw-actions">${button('analysis-save','保存分析',true)}${button('analysis-copy','复制给医生')}</div>`);}
 async function saveVideoAnalysis(shouldCopy){rememberAnalysisDraft();const doctor=host.doctors.find(item=>item.id===analysisDoctorId),current=videos.find(item=>item.id===analysisVideoId),text=analysisText().trim();if(!doctor||!current)throw new Error('请选择医生和视频');if(!text)throw new Error('请先填写分析内容');const token=loadingToken,record={id:analysisKey(),videoId:current.id,doctorId:doctor.id,text,at:new Date().toISOString()};await RepLocal.put(record);if(token!==loadingToken||!profile)return;analyses=analyses.filter(item=>item.id!==record.id);analyses.push(record);analysisDrafts[record.id]=text;if(shouldCopy){try{await navigator.clipboard.writeText(`${doctor.name}\n${videoTitle(current)}\n\n${text}`);host.toast('分析已保存并复制');}catch{host.toast('分析已保存，请长按复制内容');}}else host.toast('分析已保存');}
 function revoke(){urls.forEach(u=>URL.revokeObjectURL(u));urls=[];}
 function error(err){host.toast(err.name==='NotAllowedError'?'麦克风未获授权，请允许录音或上传文件':err.message||'操作未完成，请重试');}
 function refresh(){const field=document.activeElement,keepFocus=field?.id==='rw-query',selection=keepFocus?[field.selectionStart,field.selectionEnd]:null;host.refresh();if(keepFocus){const next=document.getElementById('rw-query');next?.focus({preventScroll:true});if(next&&selection)next.setSelectionRange(...selection);}}
 async function load(){try{[profile,setup,voice,narration,video,documents,links,events,labels]=await Promise.all([RepLocal.get('profile'),RepLocal.get('setup'),RepLocal.get('voice'),RepLocal.get('narration'),RepLocal.get('video'),RepLocal.all('doc:'),RepLocal.all('link:'),RepLocal.all('event:'),RepLocal.all('label:')]);[videos,analyses,trajectoryDemos]=await Promise.all([RepLocal.all('video:'),RepLocal.all('analysis:'),RepLocal.all('trajectory-demo:')]);await ensureTrajectoryDemos();await migrateVideoHistory();setup=setup||{};for(const record of [profile,setup,video,...links])if(record?.photo==='assets/representative.png')record.photo='assets/representative.jpg';ready=true;scriptKey=RepVideoTemplates.some(item=>item.id===setup.templateId)?setup.templateId:RepVideoTemplates[0].id;host.updateProfile(profile||{name:'',photo:'assets/avatar-empty.svg'});const savedChat=await RepLocal.get('knowledge-chat');for(const key of Object.keys(expertChats))expertChats[key]=Array.isArray(savedChat?.conversations?.[key])?savedChat.conversations[key]:key==='drug'&&Array.isArray(savedChat?.messages)?savedChat.messages:[];expertKey=Object.prototype.hasOwnProperty.call(EXPERTS,savedChat?.activeExpert)?savedChat.activeExpert:'drug';refresh();}catch(err){failure=err.message;ready=true;refresh();}}
 function init(config){host=config;if(window.BroadcastChannel){sessionChannel=new BroadcastChannel('knowdrug-representative-session');sessionChannel.onmessage=event=>{if(event.data?.type==='logout'){leave();chatEpoch++;host.reset();resetMemory();host.closeThen(()=>host.go('studio',true));}};}load();document.addEventListener('click',click);document.addEventListener('change',change);document.addEventListener('input',input);document.addEventListener('submit',submit);document.addEventListener('touchstart',videoTouchStart,{passive:true});document.addEventListener('touchend',videoTouchEnd,{passive:true});document.addEventListener('touchcancel',()=>{swipeStart=null;},{passive:true});document.addEventListener('keydown',event=>{if(activeRoute!=='avatar'||!event.target.matches('.rw-video-row')||!['ArrowLeft','ArrowRight'].includes(event.key))return;event.preventDefault();setVideoSwipe(event.target.closest('.rw-video-list-item'),event.key==='ArrowLeft');});window.visualViewport?.addEventListener('resize',updateKeyboard);window.visualViewport?.addEventListener('scroll',updateKeyboard);document.addEventListener('focusin',updateKeyboard);document.addEventListener('focusout',()=>setTimeout(updateKeyboard,0));document.addEventListener('keydown',ev=>{if(ev.target.id==='rw-query'&&ev.key==='Enter'&&(ev.ctrlKey||ev.metaKey)&&!ev.isComposing){ev.preventDefault();askKnowledge(ev.target.value);}});document.addEventListener('visibilitychange',()=>{if(document.hidden){recordEpoch++;RepMedia.stop(true);recording='';aborter?.abort();busy=false;const status=document.getElementById('rw-record-status');if(status)status.textContent='采集已暂停，请回到页面重新开始';}});window.addEventListener('pageshow',ev=>{if(ev.persisted)syncEvents();});window.addEventListener('focus',syncEvents);}
 async function syncEvents(){if(!ready)return;try{[events,links,videos,analyses,video]=await Promise.all([RepLocal.all('event:'),RepLocal.all('link:'),RepLocal.all('video:'),RepLocal.all('analysis:'),RepLocal.get('video')]);videos=videos.filter(record=>!record.repId||record.repId===profile?.repId);await ensureEngagementDemos();if(['doctor','insights'].includes(activeRoute))refresh();if(activeRoute==='avatar')refresh();if(activeRoute==='videoDetail')updateVideoStats();}catch{}}
 function updateVideoStats(){const current=selectedVideo();if(!current)return;const stats=document.getElementById('rw-library-stats'),doctors=document.getElementById('rw-library-doctors'),total=document.querySelector('.rw-video-total');if(stats)stats.innerHTML=videoStatsMarkup(current);if(doctors)doctors.innerHTML=videoDoctorsMarkup(current);if(total)total.textContent=`${videos.length} 个视频`;}
 function updateKeyboard(){const vv=window.visualViewport,offset=vv&&(!vv.scale||vv.scale<1.05)?Math.max(0,window.innerHeight-vv.height-vv.offsetTop):0;const active=activeRoute==='knowledge'&&document.activeElement?.id==='rw-query'&&offset>100;document.body.classList.toggle('rw-keyboard-open',active);document.documentElement.style.setProperty('--rw-keyboard-offset',active?offset+'px':'0px');}
 function leave(){loadingToken++;checking=false;swipeStart=null;swipeSuppressClickUntil=0;const loading=document.getElementById('rw-loading');if(loading?.open)loading.close();document.body.classList.remove('rw-keyboard-open');document.documentElement.style.setProperty('--rw-keyboard-offset','0px');recordEpoch++;RepMedia.stop(true);recording='';aborter?.abort();aborter=null;busy=false;revoke();}
 function owns(route){return ['avatar','videoDetail','studio','modelComplete','welcome','preview','scripts','knowledge','answerVideo'].includes(route);}
 function render(route,params){activeRoute=route;activeParams=params||{};document.body.classList.toggle('rw-avatar-has-video',route==='avatar'&&!!profile&&videos.length>0);activeDoctor=activeParams.id||'';if(route==='videoDetail'&&activeParams.id)libraryVideoId=activeParams.id;if(!owns(route))return null;revoke();if(!ready)return blank('正在读取本机资料…');if(failure)return `<section class="panel rw-card"><h2>资料库未能打开</h2><p>${e(failure)}</p>${button('retry','重新读取')}</section>`;return ({avatar:avatar,videoDetail:videoDetail,studio:studio,modelComplete:modelComplete,welcome:welcome,preview:preview,scripts:scripts,knowledge:knowledge,answerVideo:answerVideo})[route]();}
 function avatar(){
  if(!profile)return `<section class="rw-avatar-onboard"><div class="rw-onboard-portrait"><img src="assets/avatar-empty.svg" alt="待创建的数字人形象"></div><h2>创建我的数字人</h2><p>上传形象照片，采集您的声音，建立专属数字人形象。</p>${button('setup','创建数字人')}</section>`;
  if(videos.length)return digitalVideos();
  return `<section class="rw-avatar-pending"><img src="${e(profile.photo)}" alt="${e(profile.name)}的数字人形象"><div><h2>${e(profile.name)}</h2><span>形象已建立</span></div><p>尚未生成数字人视频</p></section><section class="panel rw-card rw-first-video-card"><h3>创建首个数字人视频</h3><p>先录制欢迎视频，向医生介绍自己。</p>${button('welcome','创建欢迎视频')}</section>`;
 }

 function studio(){return studioStep===1?`<div class="rw-page-title"><h2>录入我的形象</h2><span>1 / 2</span></div><div class="rw-enrol-steps"><span class="active">形象照片</span><i></i><span>声纹采集</span></div><section class="panel rw-card"><label class="rw-label" for="rw-name">姓名</label><input id="rw-name" class="rw-input" maxlength="16" value="${e(setup.name||profile?.name||'')}" placeholder="输入您的姓名"></section><section class="panel rw-card"><h3>上传照片</h3><div class="rw-portrait-upload"><img src="${e(setup.photo||'assets/avatar-empty.svg')}" alt="形象照片预览"><label class="rw-file">${setup.photo?'重新上传':'上传照片'}<input type="file" id="rw-photo" accept="image/jpeg,image/png,image/webp"></label></div><p>JPG / PNG / WebP，10 MB 内</p>${setup.photo?`<p class="rw-pass">✓ ${e(setup.photoReport||'照片校验完成')}</p>`:''}</section><div class="rw-stage-actions">${button('photo-next','下一步')}</div>`:`<div class="rw-page-title"><h2>声纹采集</h2><span>2 / 2</span></div><div class="rw-enrol-steps"><span class="complete">形象照片</span><i></i><span class="active">声纹采集</span></div><section class="panel rw-card"><h3>朗读以下内容</h3><p class="rw-reading">${VOICE_TEXT}</p><p>请在安静环境自然朗读，单段不超过 90 秒。</p><div class="rw-actions">${button('record-voice','开始采集')}${button('stop-record','结束录音',true)}</div><div class="rw-record-status" id="rw-record-status" role="status"></div><label class="rw-file rw-file-sub">上传已有录音<input id="rw-voice" type="file" accept="audio/*"></label>${voice?`<p class="rw-pass">✓ ${e(voice.report)}</p><audio controls src="${objectURL(voice.blob)}"></audio>`:''}</section><section class="panel rw-card"><label class="rw-check"><input id="rw-rights" type="checkbox" ${setup.rights?'checked':''}>我确认照片、录音属于本人，并同意用于建立此数字人形象</label></section><div class="rw-stage-actions">${button('photo-back','上一步',true)}${button('build','创建数字人')}</div>`;}
 function myMarkup(){const p=profile;return `<div class="rw-my-profile"><img src="${e(p?.photo||'assets/avatar-empty.svg')}" alt="我的头像"><div><h3>${e(p?.name||'尚未设置数字人')}</h3><span>${p?'数字人已建立':'待录入材料'}</span></div></div><button class="rw-link-row" data-rw="my-avatar"><span>${p?'编辑数字人形象':'创建数字人形象'}</span><b>${p?'编辑形象':'开始创建'} ›</b></button><button class="rw-logout" data-rw="logout">注销</button>`;}
 function modelComplete(){if(!profile)return avatar();return `<section class="rw-avatar-onboard rw-model-complete"><div class="rw-onboard-portrait"><img src="${e(profile.photo)}" alt="${e(profile.name)}的数字人形象"><span class="rw-complete-check" aria-hidden="true">✓</span></div><h2>数字人建模完成</h2><p>${e(profile.name)}，您的数字人形象已创建。</p><div class="rw-complete-actions">${button('welcome','创建欢迎视频')}${button('avatar','查看我的数字人',true)}</div></section>`;}
 function ensureLoading(){let dialog=document.getElementById('rw-loading');if(!dialog){dialog=document.createElement('dialog');dialog.id='rw-loading';dialog.className='rw-loading';dialog.setAttribute('aria-labelledby','rw-loading-title');dialog.setAttribute('aria-busy','true');dialog.innerHTML='<div class="rw-spinner" aria-hidden="true"></div><h2 id="rw-loading-title" role="status"></h2><p id="rw-loading-detail" hidden></p><p id="rw-loading-time" aria-hidden="true" hidden></p>';dialog.addEventListener('cancel',ev=>ev.preventDefault());document.body.append(dialog);}return MobileCompat.prepareDialog(dialog);}
 async function withLoading(title,operation,{duration=950,detail='',countdown=false}={}){const token=++loadingToken,dialog=ensureLoading(),started=Date.now(),note=dialog.querySelector('#rw-loading-detail'),time=dialog.querySelector('#rw-loading-time');let timer;checking=true;dialog.querySelector('h2').textContent=title;note.textContent=detail;note.hidden=!detail;time.hidden=!countdown;const update=()=>{if(token===loadingToken)time.textContent=`预计剩余 ${Math.max(0,Math.ceil((duration-(Date.now()-started))/1000))} 秒`;};if(countdown){update();timer=setInterval(update,250);}if(!dialog.open)dialog.showModal();try{const [result]=await Promise.all([operation(),new Promise(resolve=>setTimeout(resolve,duration))]);return result;}finally{clearInterval(timer);if(token===loadingToken){checking=false;if(dialog.open)dialog.close();}}}
 function resetMemory(){swipeStart=null;swipeSuppressClickUntil=0;videoFilter='all';welcomeDraft='';welcomeFromDetail=false;for(const controller of chatControllers.values())controller.abort();chatControllers.clear();for(const thinking of expertThinking.values())clearTimeout(thinking.timer);expertThinking.clear();profile=voice=narration=video=null;setup={};documents=[];links=[];events=[];labels=[];expertKey='drug';expertChats={drug:[],insurance:[],compliance:[]};expertDrafts={drug:'',insurance:'',compliance:''};expertPending.clear();expertStreaming.clear();query='';results=null;scriptKey=RepVideoTemplates[0].id;studioStep=1;photoBusy=false;videos=[];analyses=[];trajectoryDemos=[];libraryVideoId=inviteVideoId=analysisVideoId=analysisDoctorId='';analysisDrafts={};}
 async function logout(){const clearButton=document.querySelector('[data-rw="confirm-logout"]');if(clearButton)clearButton.disabled=true;leave();chatEpoch++;await withLoading('正在清除资料…',async()=>{await RepLocal.clear();host.reset();});resetMemory();sessionChannel?.postMessage({type:'logout'});host.closeThen(()=>{host.go('studio',true);host.toast('已注销，请重新上传材料');});}
 function welcome(){if(!profile)return avatar();const existing=orderedVideos().find(item=>item.templateId==='welcome');return `<div class="rw-page-title"><h2>创建欢迎视频</h2></div><section class="panel rw-card rw-welcome-editor"><div class="rw-welcome-avatar"><img src="${e(profile.photo)}" alt="${e(profile.name)}的数字人"><div><strong>${e(profile.name)}的欢迎视频</strong><span>写下您希望对医生说的话</span></div></div><label class="rw-label" for="rw-welcome-script">欢迎语</label><textarea id="rw-welcome-script" class="rw-input" rows="9" maxlength="800">${e(welcomeDraft||existing?.script||WELCOME_TEXT)}</textarea><div class="rw-welcome-editor-actions">${button('welcome-create',existing?'生成新版本':'生成欢迎视频')}${button('scripts','选择其他话术',true)}</div></section>`;}
 function scripts(){if(!profile)return `<section class="panel rw-card"><h2>先建立您的数字人</h2><p>上传照片并完成声音采集后，即可选择话术模板。</p>${button('setup','开始录入')}</section>`;const welcomeGenerated=videos.some(record=>record.templateId==='welcome');return `<div class="rw-page-title"><h2>选择本次话术</h2></div><section class="panel rw-card"><div class="rw-template-grid rw-video-templates"><button type="button" class="rw-template rw-welcome-template" data-rw="welcome"><span class="rw-template-content"><strong class="rw-template-title">欢迎视频</strong><span class="rw-template-meta"><span>发布人：${e(profile.name)}</span><span>自定义欢迎语</span></span><span class="rw-template-tag ${welcomeGenerated?'generated':''}">${welcomeGenerated?'已生成':'未生成'}</span></span><span aria-hidden="true">›</span></button>${RepVideoTemplates.map(item=>{const generated=videos.some(record=>record.templateId===item.id);return `<button type="button" class="rw-template" data-rw-template="${item.id}" aria-label="${e(item.title)}，生成视频" ${busy||checking?'disabled':''}><span class="rw-template-content"><strong class="rw-template-title">${e(item.title)}</strong><span class="rw-template-meta"><span>发布人：${e(item.publisher)}</span><time datetime="${item.publishedAt}">发布时间：${publishDate(item.publishedAt)}</time></span><span class="rw-template-tag ${generated?'generated':''}">${generated?'已生成':'未生成'}</span></span><span aria-hidden="true">›</span></button>`;}).join('')}</div></section>`;}
 function preview(){if(!video)return `<section class="panel rw-card"><h2>还没有介绍视频</h2>${button('scripts','选择话术模板')}</section>`;const template=videoTemplate(video),src=videoSource(video),type=video.blob?.type||'video/mp4';return `<section class="panel rw-card"><div class="rw-heading"><h2>${e(template?.title||video.name+'的介绍')}</h2><span class="tag">${fmt(video.at)}</span></div><video class="rw-video ${template?'rw-template-video':''}" playsinline webkit-playsinline controls controlslist="nodownload" preload="auto" poster="${e(videoPoster(video))}" src="${e(src)}" data-fallback-src="${e(videoFallback(video))}"></video>${template?'':`<p class="rw-reading">${e(video.script)}</p>`}<div class="rw-actions">${button('share','生成分享链接')}</div><button class="text-btn" data-rw="scripts">选择其他话术</button></section>`;}

 const doctorOptions=()=>'<option value="">请选择指定医生</option>'+host.doctors.map(d=>`<option value="${d.id}">${e(d.name)} · ${e(d.hospital)}</option>`).join('');
 function linkURL(link,view,preview=false){const url=new URL('share.html',location.href);url.searchParams.set('rep',link.repId);url.searchParams.set('share',link.id.slice(5));url.searchParams.set('doctor',link.doctorId);url.searchParams.set('view',view);if(preview)url.searchParams.set('preview','1');return url.href;}
 function openInvitation(videoId){const current=videos.find(item=>item.id===videoId)||selectedVideo()||video;if(!current){host.toast('请先创建数字人视频');return;}inviteVideoId=current.videoId||current.id;document.getElementById('rw-library-video')?.pause();host.modal('邀请医生',`<div class="rw-invite-video rw-invite-preview"><img src="${e(videoPoster(current))}" alt="${e(videoTitle(current))}封面"><div><strong>${e(videoTitle(current))}</strong><time>创建于 ${fullDate(current.at)}</time></div></div><label class="rw-label" for="rw-link-doctor">选择医生</label><select id="rw-link-doctor" class="rw-input">${doctorOptions()}</select><div class="rw-invite-share-actions"><button type="button" class="primary-button" data-rw="copy-invite-link">复制链接</button><button type="button" class="secondary-button" data-rw="wechat-share">微信分享</button></div>`);}

 const EXPERTS={
  drug:{name:'药品专家',questions:['有哪些日达仙药品资料？','如何查阅日达仙用法用量？','日达仙用药安全有哪些核对要点？'],followUps:['合并用药需要核对哪些资料？','如何核对特殊人群的说明书条目？','如何记录不良反应相关资料出处？','如何核对说明书的版本与来源？']},
  insurance:{name:'保险专家',questions:['创新支付服务如何申请？','申请材料需要核对哪些内容？','如何查看服务申请审核进度？'],followUps:['申请材料不齐时如何整理补充清单？','如何核对保障范围与服务规则？','如何梳理需要向服务团队确认的问题？','服务开通后还需要核对哪些信息？']},
  compliance:{name:'合规专家',questions:['对外沟通话术如何做资料核对？','患者资料使用前需要确认什么？','学术材料发布前应检查哪些内容？'],followUps:['如何保留材料审核记录？','分享链接前需要核对什么？','如何核对资料版本与使用范围？','如何整理患者资料的授权与脱敏核对清单？']}
 };
 function followUpQuestions(question,key){const related=key==='drug'&&/指南|研究|文献/.test(question)?['阅读研究时如何核对适用人群？','如何记录指南资料的来源？','不同研究结论不一致时如何梳理？']:EXPERTS[key].followUps;return [...new Set([...related,...EXPERTS[key].questions])].filter(text=>text!==question).slice(0,3);}

 function expertSelector(){return `<section class="rw-expert-selector" aria-labelledby="rw-expert-label"><h3 id="rw-expert-label">专家选择</h3><div class="rw-expert-options" role="group" aria-label="专家选择">${Object.entries(EXPERTS).map(([key,expert])=>`<button type="button" data-rw-expert="${key}" class="${key===expertKey?'active':''}" aria-pressed="${key===expertKey}">${expert.name}</button>`).join('')}</div></section>`;}
 function thinkingMarkup(step,avatar){return `<article class="kd-thinking-card" role="status" aria-live="polite"><div class="kd-thinking-head"><img src="${e(avatar)}" alt="数字人助手"><strong>正在查询</strong></div><div class="kd-thinking-steps">${['正在识别意图','正在查询专属数据库'].map((label,index)=>`<div class="kd-thinking-step ${index<step?'is-done':index===step?'is-active':''}" ${index===step?'aria-current="step"':''}><span class="kd-thinking-icon" aria-hidden="true"></span><span>${label}</span></div>`).join('')}</div></article>`;}
 function streamMarkup(key,expert){const draft=expertStreaming.get(key),thinking=thinkingMarkup(expertThinking.get(key)?.step||0,profile?.photo||'assets/representative.jpg');if(!draft?.text)return thinking;return thinking+`<div class="rw-chat-message assistant rw-chat-streaming"><img src="${e(profile?.photo||'assets/representative.jpg')}" alt="数字人助手"><div class="rw-chat-answer"><span class="rw-answer-expert">${expert.name}</span><p id="rw-stream-body">${e(draft.text)}</p><span class="rw-stream-status">正在生成<span aria-hidden="true">▍</span></span></div></div>`;}
 function knowledge(){const expert=EXPERTS[expertKey],messages=expertChats[expertKey],pending=expertPending.has(expertKey);let lastQuestion='';return `<section class="rw-agent"><header class="rw-agent-heading"><img src="${e(profile?.photo||'assets/representative.jpg')}" alt="数字人助手"><h2>日达仙</h2><button type="button" class="rw-new-chat" data-rw="new-chat" aria-label="新建问答">＋</button></header>${messages.length?'':`<div class="rw-agent-welcome"><h3>问问${expert.name}</h3><div class="rw-question-list">${expert.questions.map((q,i)=>`<button data-rw-question="${i}" data-question-expert="${expertKey}">${e(q)}<span>›</span></button>`).join('')}</div></div>`}<div class="rw-chat-messages" aria-live="polite">${messages.map((message,i)=>{if(message.role==='error')return `<div class="rw-chat-error" role="status"><p>${e(message.text)}</p><button class="text-btn" data-rw-retry="${i}">重新回答</button></div>`;if(message.role==='user'){lastQuestion=message.text;return `<div class="rw-chat-message user"><div>${e(message.text)}</div></div>`;}const related=Array.isArray(message.followUps)&&message.followUps.length===3?message.followUps:followUpQuestions(lastQuestion,expertKey);return `<div class="rw-chat-message assistant"><img src="${e(profile?.photo||'assets/representative.jpg')}" alt="数字人助手"><div class="rw-chat-answer"><span class="rw-answer-expert">${expert.name}</span><h3>${e(message.answer.title)}</h3><p>${e(message.answer.body)}</p>${message.answer.sources?.length?`<div class="rw-chat-sources">${message.answer.sources.map((source,index)=>`<span>[${index+1}] ${e(source.name)} · 第 ${source.section} 段</span>`).join('')}</div>`:''}<div class="rw-answer-tools"><button type="button" class="rw-answer-video-button" data-rw-answer-video="${i}" data-question-expert="${expertKey}">生成数字人视频</button><button class="text-btn" data-rw-answer-copy="${i}">复制回答</button></div><div class="rw-followup"><h4>猜你想问</h4>${related.map((question,index)=>`<button type="button" data-rw-followup="${index}" data-answer-index="${i}" data-question-expert="${expertKey}">${e(question)}<span>›</span></button>`).join('')}</div></div></div>`;}).join('')}${pending?streamMarkup(expertKey,expert):''}</div></section><div class="rw-chat-composer">${expertSelector()}<form id="rw-chat-form"><label class="sr-only" for="rw-query">${expert.name}问题</label><textarea id="rw-query" rows="2" maxlength="1000" placeholder="向${expert.name}提问" enterkeyhint="enter">${e(query)}</textarea><div><button class="rw-chat-send" type="submit" ${pending?'disabled':''}>发送</button></div></form></div>`;}
 function answerVideoContent(params=activeParams){if(params.sourceVideoId)return videos.find(item=>item.id===params.sourceVideoId&&item.templateId===RepKnowledgeVideo.id)?.script||'';const message=expertChats[params.expert]?.[Number(params.index)];if(message?.role!=='assistant'||!message.answer)return '';return [message.answer.title,message.answer.body].filter(Boolean).join('\n\n').trim();}
 function answerVideo(){const script=answerVideoContent();if(!script)return `<section class="panel rw-card"><h2>回答未找到</h2>${button('knowledge','返回知识库')}</section>`;return `<section class="panel rw-card rw-answer-video-editor"><div class="rw-heading"><h2>生成数字人视频</h2><span class="rw-video-kind">知识问答</span></div><div class="rw-answer-video-preview"><img src="${e(RepKnowledgeVideo.poster)}" alt="视频封面"><div><strong>${e(RepKnowledgeVideo.title)}</strong><span>生成后将添加到我的数字人视频列表</span></div></div><label class="rw-label" for="rw-answer-video-script">本次回答</label><textarea id="rw-answer-video-script" class="rw-input" rows="9" readonly aria-readonly="true">${e(script)}</textarea><div class="rw-answer-video-actions">${profile?button('answer-video-create','开始生成'):button('setup','先创建数字人形象')}${button('knowledge','返回知识库',true)}</div></section>`;}
 async function persistKnowledge(){await RepLocal.put({id:'knowledge-chat',activeExpert:expertKey,conversations:expertChats});}
 async function switchExpert(key){if(!Object.prototype.hasOwnProperty.call(EXPERTS,key)||key===expertKey)return;expertDrafts[expertKey]=query;expertKey=key;query=expertDrafts[key];refresh();try{await persistKnowledge();}catch(err){error(err);}}
 async function askKnowledge(question){const text=question.trim(),key=expertKey;if(!text||expertPending.has(key))return;const epoch=chatEpoch,controller=new AbortController();chatControllers.set(key,controller);query='';expertDrafts[key]='';expertPending.add(key);const thinking={step:0,timer:null};expertThinking.set(key,thinking);thinking.timer=setTimeout(()=>{if(epoch!==chatEpoch||!expertPending.has(key))return;thinking.step=1;if(activeRoute==='knowledge'&&expertKey===key)refresh();},700);expertChats[key].push({role:'user',text,transport:'deepseek'});refresh();try{const result=await RepKnowledgeAPI.ask(key,text,expertChats[key],controller.signal,chunk=>{if(epoch!==chatEpoch||controller.signal.aborted)return;let draft=expertStreaming.get(key);if(!draft){draft={text:''};expertStreaming.set(key,draft);}draft.text+=chunk;thinking.step=1;clearTimeout(thinking.timer);thinking.timer=null;if(activeRoute==='knowledge'&&expertKey===key){const body=document.getElementById('rw-stream-body');if(body)body.textContent=draft.text;else refresh();}});if(epoch!==chatEpoch)return;expertChats[key].push({role:'assistant',answer:result.answer,expert:key,provider:'deepseek',followUps:result.followUps});expertChats[key]=expertChats[key].slice(-60);await persistKnowledge();}catch(err){if(epoch===chatEpoch&&err.name!=='AbortError'){expertChats[key].push({role:'error',text:err.message||'暂时无法获取回答，请重试'});await persistKnowledge().catch(error);}}finally{if(expertThinking.get(key)===thinking){clearTimeout(thinking.timer);expertThinking.delete(key);}if(chatControllers.get(key)===controller)chatControllers.delete(key);if(epoch===chatEpoch){expertPending.delete(key);expertStreaming.delete(key);if(activeRoute==='knowledge'){refresh();if(expertKey===key)document.getElementById('rw-chat-form')?.scrollIntoView?.({behavior:'smooth',block:'nearest'});}}}}

 function doctorLabel(id){const index=Math.max(0,host.doctors.findIndex(d=>d.id===id));const base={kol:options.kol[1+index%4],stage:options.stage[1+index%4],payment:options.payment[1+index%4],title:['主任医师','副主任医师','主治医师'][index%3],region:['上海','杭州','南京'][index%3],note:''};return {...base,...labels.find(l=>l.id==='label:'+id)};}
 function tags(id){const l=doctorLabel(id);return `<span class="tag">${e(l.kol)}</span><span class="tag">${e(l.stage)}</span><span class="tag">${e(l.payment)}</span>`;}
 async function ensureTrajectoryDemos(){const changed=[];for(const doctor of host.doctors){const id='trajectory-demo:'+doctor.id;if(trajectoryDemos.some(record=>record.id===id))continue;const now=Date.now(),samples=[],visits=randomCount(2,4);for(let visit=0;visit<visits;visit++){const at=now-randomCount(1,6)*86400000-visit*3600000-randomCount(5,120)*60000,view=visit%2?'video':'entry',template=RepVideoTemplates[visit%RepVideoTemplates.length];for(const [type,delta] of [['open',0],['play',12000],['complete',42000],['ask',90000]]){samples.push({id:`${id}:${visit}:${type}`,doctorId:doctor.id,type,view,at:new Date(at+delta).toISOString(),seconds:type==='complete'?30:undefined,question:type==='ask'?`关于《${template.title}》，还有哪些日达仙资料可供查阅？`:undefined});}}const record={id,events:samples};trajectoryDemos.push(record);changed.push(record);}if(changed.length)await RepLocal.putMany(changed);}
 const typeLabels={open:'浏览邀请链接',play:'观看数字人视频',complete:'完成视频观看',ask:'提出药品问题'};
 function trajectory(id){const filtered=[...events.filter(ev=>ev.doctorId===id),...(trajectoryDemos.find(item=>item.id==='trajectory-demo:'+id)?.events||[])].sort((a,b)=>b.at.localeCompare(a.at));const count=t=>filtered.filter(ev=>ev.type===t).length;return `<section class="panel rw-card"><div class="rw-heading"><h3>链接行为轨迹</h3><button class="text-btn" data-rw="sync">刷新</button></div><div class="rw-mini-stats"><span><b>${count('open')}</b>浏览</span><span><b>${count('play')}</b>视频播放</span><span><b>${count('complete')}</b>看完</span><span><b>${count('ask')}</b>提问</span></div>${filtered.length?`<ol class="rw-timeline">${filtered.slice(0,80).map(ev=>`<li><div><strong>${typeLabels[ev.type]||'互动'}</strong><time>${fmt(ev.at)}</time></div>${ev.question?`<p>${e(ev.question)}</p>`:''}<span>${e(ev.view==='video'?'视频链接':'代表身份链接')}${ev.seconds!=null?' · 观看 '+Math.round(ev.seconds)+' 秒':''}</span></li>`).join('')}</ol>`:blank('尚无链接浏览、观看或提问记录')}</section>`;}
 function doctorPanel(id){activeDoctor=id;const applications=PAYMENT_APPLICATIONS.filter(row=>row.doctorId===id),active=applications.filter(row=>row.status==='active').length,pending=applications.filter(row=>['reviewing','needs_info'].includes(row.status)).length;return `<section class="panel rw-card rw-payment-card"><div class="rw-heading"><h3>对应医生创支服务情况</h3><span class="tag">日达仙</span></div><div class="rw-payment-metrics"><div><strong>${new Set(applications.map(row=>row.patientId)).size}</strong><span>申请患者</span></div><div><strong>${active}</strong><span>服务已开通</span></div><div><strong>${pending}</strong><span>处理中</span></div></div></section>${trajectory(id)}`;}
 async function persistSetup(){await RepLocal.put({...setup,id:'setup',templateId:scriptKey});}
 async function audioDone(blob,kind,epoch){try{const report=await withLoading(kind==='voice'?'正在校验声纹质量…':'正在检查话术录音…',()=>RepMedia.audio(blob),{duration:kind==='voice'?2000:950,detail:kind==='voice'?'正在检查录音清晰度与声音完整性':''});if(epoch!==recordEpoch)return;const record={id:kind==='voice'?'voice':'narration',blob,...report,report:kind==='voice'?`${Math.round(report.duration)} 秒 · 声纹质量校验通过`:report.report,script:VOICE_TEXT,at:new Date().toISOString()};await RepLocal.put(record);if(epoch!==recordEpoch)return;if(kind==='voice')voice=record;else narration=record;recording='';refresh();host.toast(kind==='voice'?'声纹质量校验通过':'话术录音已保存');}catch(err){if(epoch===recordEpoch){recording='';refresh();error(err);}}}
 async function copy(text){try{await navigator.clipboard.writeText(text);host.toast('链接已复制');}catch{host.modal('复制链接',`<p>长按下方链接进行复制。</p><textarea class="rw-input" rows="5" readonly>${e(text)}</textarea>`);}}
 async function createLink(){const current=invitationVideo();if(!current||!profile)throw new Error('请先生成本次介绍视频');const doctorId=document.getElementById('rw-link-doctor')?.value;if(!host.doctors.some(d=>d.id===doctorId))throw new Error('请选择要邀请的医生');const existing=links.filter(link=>link.doctorId===doctorId&&linkedVideo(link)?.id===(current.videoId||current.id)).sort((a,b)=>Date.parse(b.at)-Date.parse(a.at))[0];if(existing)return existing;const link={id:RepLocal.uid('link:'),repId:profile.repId,doctorId,name:current.name,role:current.role,script:current.script,photo:current.photo,blob:current.blob,templateId:current.templateId,videoId:current.videoId||current.id,at:new Date().toISOString()};await RepLocal.put(link);links.unshift(link);updateVideoStats();return link;}
 function setVideoSwipe(card,open){for(const other of document.querySelectorAll('.rw-video-list-item.is-open'))if(other!==card){other.classList.remove('is-open');other.querySelectorAll('.rw-video-swipe-actions button').forEach(button=>button.tabIndex=-1);}card.classList.toggle('is-open',open);card.querySelectorAll('.rw-video-swipe-actions button').forEach(button=>button.tabIndex=open?0:-1);}
 function videoTouchStart(event){const card=event.target.closest('.rw-video-list-item');if(activeRoute!=='avatar'||!card||event.touches.length!==1){swipeStart=null;return;}swipeStart={card,x:event.touches[0].clientX,y:event.touches[0].clientY};}
 function videoTouchEnd(event){if(!swipeStart||!event.changedTouches.length)return;const {card,x,y}=swipeStart;swipeStart=null;const dx=event.changedTouches[0].clientX-x,dy=event.changedTouches[0].clientY-y;if(Math.abs(dx)<45||Math.abs(dx)<Math.abs(dy)*1.2)return;setVideoSwipe(card,dx<0);swipeSuppressClickUntil=Date.now()+500;}

 async function saveGeneratedVideo(templateId,script,blob){const now=new Date().toISOString(),next={id:'video',templateId,repId:profile.repId,name:profile.name,role:profile.role,photo:profile.photo,script,blob:blob||undefined,at:now,engagementDemo:makeEngagementDemo()};const archived={...next,id:RepLocal.uid('video:')};next.videoId=archived.id;archived.videoId=archived.id;await RepLocal.putMany([archived,next]);videos.unshift(archived);video=next;libraryVideoId=archived.id;videoFilter='all';}
 async function generateVideo(template,script,route){if(busy||checking||!profile)return;const duration=(10+Math.floor(Math.random()*6))*1000,token=loadingToken+1;busy=true;try{await withLoading('正在生成数字人视频…',async()=>{},{duration,detail:template.title,countdown:true});if(token!==loadingToken||activeRoute!==route)return;await saveGeneratedVideo(template.id,script);if(token!==loadingToken)return;scriptKey=template.id;await persistSetup();host.go(route==='videoDetail'?'videoDetail':'avatar',route==='videoDetail'?{id:libraryVideoId}:{});}finally{if(token===loadingToken)busy=false;}}
 async function generateAnswerVideo(){if(busy||checking)return;if(!profile)throw new Error('请先创建数字人形象');const script=answerVideoContent(),token=loadingToken+1;if(!script)throw new Error('对应回答已不存在，请返回知识库重新选择');busy=true;try{await withLoading('正在生成数字人视频…',async()=>{},{duration:10000,detail:RepKnowledgeVideo.title,countdown:true});if(token!==loadingToken||activeRoute!=='answerVideo')return;await saveGeneratedVideo(RepKnowledgeVideo.id,script);if(token!==loadingToken)return;host.go('avatar');host.toast('数字人视频已生成');}finally{if(token===loadingToken)busy=false;}}
 async function generateWelcome(){if(busy||checking||!profile)return;const script=(document.getElementById('rw-welcome-script')?.value||'').trim();if(!script)throw new Error('请填写欢迎语');if(script.length>800)throw new Error('欢迎语最多 800 字');welcomeDraft=script;const token=loadingToken+1,duration=8000;busy=true;try{await withLoading('正在生成欢迎视频…',async()=>{},{duration,detail:'正在准备您的数字人欢迎视频',countdown:true});if(token!==loadingToken||activeRoute!=='welcome')return;await saveGeneratedVideo('welcome',script);if(token!==loadingToken)return;welcomeDraft='';const destination=welcomeFromDetail?'videoDetail':'avatar';welcomeFromDetail=false;host.go(destination,destination==='videoDetail'?{id:libraryVideoId}:{});}finally{if(token===loadingToken)busy=false;}}
 async function deleteVideo(id){const current=videos.find(item=>item.id===id);if(!current)return;const related=links.filter(link=>linkedVideo(link)?.id===id),ids=new Set(related.map(link=>link.id));const toDelete=[id,...related.map(link=>link.id),...events.filter(item=>ids.has(item.linkId)).map(item=>item.id),...analyses.filter(item=>item.videoId===id).map(item=>item.id)];await Promise.all(toDelete.map(recordId=>RepLocal.remove(recordId)));videos=videos.filter(item=>item.id!==id);links=links.filter(item=>!ids.has(item.id));events=events.filter(item=>!ids.has(item.linkId));analyses=analyses.filter(item=>item.videoId!==id);if(video?.videoId===id){video=null;await RepLocal.remove('video');}if(libraryVideoId===id)libraryVideoId=orderedVideos()[0]?.id||'';if(!videos.some(item=>videoTag(item)===videoFilter))videoFilter='all';host.closeThen(()=>{host.go('avatar');host.toast('视频已删除');});}
 async function click(ev){const target=ev.target.closest('button,a');if(!target)return;
  try{if(target.dataset.rwVideo){libraryVideoId=target.dataset.rwVideo;host.go('videoDetail',{id:libraryVideoId});return;}if(target.dataset.rwCopy){const link=links.find(l=>l.id===target.dataset.rwCopy);if(link)await copy(linkURL(link,target.dataset.view));return;}
   if(target.dataset.rwSelect){if(Date.now()<swipeSuppressClickUntil)return;libraryVideoId=target.dataset.rwSelect;host.go('videoDetail',{id:libraryVideoId});return;}
   if(target.dataset.rwFilter){videoFilter=target.dataset.rwFilter;const first=orderedVideos().find(item=>videoFilter==='all'||videoTag(item)===videoFilter);if(first)libraryVideoId=first.id;refresh();return;}
   if(target.dataset.rwRegenerate){const current=videos.find(item=>item.id===target.dataset.rwRegenerate);if(!current)return;if(current.templateId==='welcome'){welcomeDraft=current.script;welcomeFromDetail=activeRoute==='videoDetail';host.go('welcome');return;}if(current.templateId===RepKnowledgeVideo.id){host.go('answerVideo',{sourceVideoId:current.id});return;}const template=videoTemplate(current);if(template)await generateVideo(template,current.script,activeRoute);return;}
   if(target.dataset.rwDelete){const current=videos.find(item=>item.id===target.dataset.rwDelete);if(!current)return;host.modal('删除视频',`<div class="rw-invite-video"><img src="${e(videoPoster(current))}" alt=""><div><strong>${e(videoTitle(current))}</strong><time>创建于 ${fullDate(current.at)}</time></div></div><p>删除后，这条视频及对应的邀请链接将无法恢复。</p><div class="rw-actions"><button type="button" class="secondary-button" data-rw="delete-cancel">取消</button><button type="button" class="rw-logout rw-delete-confirm" data-rw-confirm-delete="${e(current.id)}">删除视频</button></div>`);return;}
   if(target.dataset.rwConfirmDelete){await deleteVideo(target.dataset.rwConfirmDelete);return;}
   if(target.dataset.rwTemplate){const template=RepVideoTemplates.find(item=>item.id===target.dataset.rwTemplate);if(template)await generateVideo(template,template.title,'scripts');return;}

   if(target.dataset.rwRetry!==undefined){const index=Number(target.dataset.rwRetry),previous=expertChats[expertKey][index-1];if(previous?.role==='user'){if(index===expertChats[expertKey].length-1)expertChats[expertKey].splice(index-1,2);await askKnowledge(previous.text);}return;}if(target.dataset.rwExpert){await switchExpert(target.dataset.rwExpert);return;}if(target.dataset.rwQuestion!==undefined){if(target.dataset.questionExpert===expertKey)await askKnowledge(EXPERTS[expertKey].questions[Number(target.dataset.rwQuestion)]||'');return;}if(target.dataset.rwFollowup!==undefined){if(target.dataset.questionExpert!==expertKey)return;const index=Number(target.dataset.answerIndex),message=expertChats[expertKey][index],previous=expertChats[expertKey][index-1];if(!message?.answer)return;const related=Array.isArray(message.followUps)&&message.followUps.length===3?message.followUps:followUpQuestions(previous?.text||'',expertKey);await askKnowledge(related[Number(target.dataset.rwFollowup)]||'');return;}if(target.dataset.rwAnswerVideo!==undefined){const index=Number(target.dataset.rwAnswerVideo),key=target.dataset.questionExpert;if(expertChats[key]?.[index]?.role==='assistant')host.go('answerVideo',{expert:key,index});return;}if(target.dataset.rwAnswerCopy!==undefined){const answer=expertChats[expertKey][Number(target.dataset.rwAnswerCopy)]?.answer;if(answer){try{await navigator.clipboard.writeText(answer.title+'\n'+answer.body);host.toast('回答已复制');}catch{host.toast('请长按回答文字复制');}}return;}
   const action=target.dataset.rw;if(!action)return;if((busy||checking)&&action!=='stop-record')return;
   if(action==='video-library'){libraryVideoId=orderedVideos()[0]?.id||'';host.go('avatar');return;}if(action==='video-analyze'){openVideoAnalysis();return;}if(action==='analysis-save'||action==='analysis-copy'){await saveVideoAnalysis(action==='analysis-copy');return;}if(action==='video-invite'){openInvitation();return;}
   if(action==='my-avatar'){studioStep=1;host.closeThen(()=>host.go('studio'));return;}
   if(action==='logout'){host.modal('注销并清除资料',`<p>注销后，将清除本浏览器中的代表端照片、录音、视频、分享链接、问答历史、医生标签和跟进记录。您需要重新上传材料设置数字人。</p><button class="rw-logout rw-logout-confirm" data-rw="confirm-logout">注销并清除资料</button><button class="secondary-button full" data-rw="cancel-logout">取消</button>`);return;}
   if(action==='cancel-logout'||action==='delete-cancel'){host.closeThen(()=>{});return;}
   if(action==='confirm-logout'){try{await logout();}finally{target.disabled=false;}return;}
   if(action==='photo-next'){if(!setup.name?.trim())throw new Error('请填写姓名');if(!setup.photo)throw new Error('请先上传照片');studioStep=2;refresh();window.scrollTo({top:0,behavior:'instant'});return;}
   if(action==='photo-back'){recordEpoch++;RepMedia.stop(true);recording='';studioStep=1;refresh();window.scrollTo({top:0,behavior:'instant'});return;}
   if(action==='new-chat'){if(expertPending.has(expertKey))throw new Error('请等待当前回答完成');expertChats[expertKey]=[];query='';expertDrafts[expertKey]='';await persistKnowledge();refresh();return;}
   if(action==='answer-video-create'){await generateAnswerVideo();return;}if(action==='welcome-create'){await generateWelcome();return;}if(action==='share'){openInvitation(video?.videoId);return;}if(['setup','avatar','welcome','scripts','preview','knowledge'].includes(action)){if(action==='setup')studioStep=1;if(action==='welcome')welcomeFromDetail=false;host.go({setup:'studio',avatar:'avatar',welcome:'welcome',scripts:'scripts',preview:'preview',knowledge:'knowledge',share:'avatar'}[action]);return;}
   if(!ready)return;if(action==='retry'){ready=false;failure='';refresh();load();return;}
   if(action==='sync'){await syncEvents();host.toast('轨迹已刷新');return;}
   if(action==='stop-record'){if(recording){RepMedia.stop();const status=document.getElementById('rw-record-status');if(status)status.textContent='正在检查录音…';}return;}
   if(action==='record-voice'){if(recording)throw new Error('请先结束当前录音');const kind='voice';const epoch=++recordEpoch;recording='starting';try{await RepMedia.start(blob=>audioDone(blob,kind,epoch),seconds=>{const el=document.getElementById('rw-record-status');if(el)el.textContent=`● 正在录音 ${seconds} 秒 / 90 秒`;});if(epoch!==recordEpoch){RepMedia.stop(true);recording='';return;}recording=kind;document.getElementById('rw-record-status').textContent='● 正在录音…';}catch(err){recording='';throw err;}return;}
   if(action==='build'){if(photoBusy)throw new Error('请等待照片校验完成');if(studioStep!==2)throw new Error('请先点击下一步完成声纹采集');if(!setup.name?.trim())throw new Error('请填写姓名');if(!setup.photo)throw new Error('请先上传照片');if(!voice)throw new Error('请完成声音采集与校验');if(recording)throw new Error('请先结束录音');if(!setup.rights)throw new Error('请确认照片与录音的使用授权');const token=loadingToken+1,next={id:'profile',repId:profile?.repId||MobileCompat.uuid(),name:setup.name.trim(),role:'日达仙医药代表',photo:setup.photo,at:new Date().toISOString()};busy=true;target.disabled=true;try{await withLoading('正在创建数字人…',async()=>{}, {duration:10000,detail:'正在建立您的专属数字人形象',countdown:true});if(token!==loadingToken||activeRoute!=='studio')return;await RepLocal.put(next);if(token!==loadingToken)return;profile=next;host.updateProfile(profile);welcomeDraft=WELCOME_TEXT;welcomeFromDetail=false;host.go('welcome');}finally{if(token===loadingToken)busy=false;target.disabled=false;}return;}

   if(action==='copy-invite-link'){const link=await createLink();await copy(linkURL(link,'entry'));return;}if(action==='wechat-share'){host.toast('请先复制链接，再到微信中分享');return;}
  }catch(err){error(err);}
 }
 async function change(ev){const el=ev.target;try{if(el.id==='rw-analysis-doctor'){rememberAnalysisDraft();analysisDoctorId=el.value;const area=document.getElementById('rw-analysis-text');if(area)area.value=analysisText();return;}
  if(el.id==='rw-photo'){if(checking||busy)return;const file=el.files[0];if(!file)return;photoBusy=true;el.disabled=true;try{const epoch=recordEpoch;const result=await withLoading('正在校验照片质量…',()=>RepMedia.photo(file),{duration:2000,detail:'正在检查照片清晰度与人像完整性'});if(epoch!==recordEpoch)return;setup={...setup,photo:result.data,photoReport:'照片质量校验通过'};await persistSetup();}finally{photoBusy=false;el.disabled=false;}if(activeRoute==='studio')refresh();return;}
  if(el.id==='rw-voice'){if(checking||busy)return;if(recording)throw new Error('请先结束当前录音');const file=el.files[0];if(file)await audioDone(file,el.id==='rw-voice'?'voice':'narration',recordEpoch);return;}
 }catch(err){error(err);}}
 function input(ev){const el=ev.target;if(el.id==='rw-analysis-text')rememberAnalysisDraft();if(['rw-name','rw-rights'].includes(el.id)){setup[{'rw-name':'name','rw-rights':'rights'}[el.id]]=el.type==='checkbox'?el.checked:el.value;persistSetup().catch(error);}if(el.id==='rw-welcome-script')welcomeDraft=el.value;if(el.id==='rw-query'){query=el.value;expertDrafts[expertKey]=query;}}

 async function submit(ev){if(ev.target.id==='rw-chat-form'){ev.preventDefault();await askKnowledge(document.getElementById('rw-query').value);return;}}
 function applyDoctors(){labels.forEach(l=>{const doctor=host.doctors.find(d=>'label:'+d.id===l.id);if(doctor&&l.name)Object.assign(doctor,{name:/^[\u4e00-\u9fff]{1,2}医生$/.test(l.name)?ORIGINAL_DOCTORS.find(item=>item.id===doctor.id).name:l.name,hospital:{'仁和医院':'复旦大学附属中山医院','江城中心医院':'上海交通大学医学院附属瑞金医院','滨江医院':'复旦大学附属华山医院'}[l.hospital]||l.hospital||doctor.hospital,department:l.department||doctor.department});});}
 return {init,owns,render,leave,tags,doctorPanel,applyDoctors,myMarkup,openInvitation};
})();
